/** One row of "sessions". Relation fields are present only when included. */
export interface Session {
  token: string;
  user_id: string;
  created_at: number;
  expires_at: number;
  user?: User | null;
}

/** Input to create; omitted optional fields defer to defaults or NULL. */
export interface SessionCreate {
  token?: string;
  user_id: string;
  created_at?: number;
  expires_at: number;
}

/** Input to update: undefined leaves a column untouched; null clears a
 * nullable column. */
export interface SessionPatch {
  user_id?: string;
  created_at?: number;
  expires_at?: number;
}

export class SessionTable {
  private v: View;
  constructor(v: View) {
    this.v = v;
  }

  async create(input: SessionCreate): Promise<Session> {
    return (await this.v.create(
      "sessions",
      input as unknown as Rec,
    )) as unknown as Session;
  }

  async get(token: string): Promise<Session | null> {
    return (await this.v.get("sessions", { token: token })) as Session | null;
  }

  async update(token: string, patch: SessionPatch): Promise<Session | null> {
    const { set, clear } = splitPatch(patch as unknown as Rec);
    return (await this.v.update(
      "sessions",
      { token: token },
      set,
      clear,
    )) as Session | null;
  }

  async delete(token: string): Promise<boolean> {
    return this.v.del("sessions", { token: token });
  }

  query(): SessionQuery {
    return new SessionQuery(this.v);
  }
}

